#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        int count = 0, current_sum = 0;
        unordered_map<int, int> prefix_counts;
        prefix_counts[0] = 1;
        for (int num : nums) {
            current_sum += num;
            if (prefix_counts.count(current_sum - k)) {
                count += prefix_counts[current_sum - k];
            }
            prefix_counts[current_sum]++;
        }
        return count;
    }
};

import java.util.HashMap;
import java.util.Map;

class Solution {
    public int subarraySum(int[] nums, int k) {
        int count = 0;
        int currentSum = 0;
        Map<Integer, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0, 1);
        for (int num : nums) {
            currentSum += num;
            count += prefixCounts.getOrDefault(currentSum - k, 0);
            prefixCounts.put(currentSum, prefixCounts.getOrDefault(currentSum, 0) + 1);
        }
        return count;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var subarraySum = function(nums, k) {
    let count = 0;
    let currentSum = 0;
    const prefixCounts = new Map([[0, 1]]);
    for (const num of nums) {
        currentSum += num;
        const needed = currentSum - k;
        if (prefixCounts.has(needed)) {
            count += prefixCounts.get(needed);
        }
        prefixCounts.set(currentSum, (prefixCounts.get(currentSum) || 0) + 1);
    }
    return count;
};
